{"scripts": {"module_wrapper.ps1": {"path": "module_wrapper.ps1", "script": ""}, "ansible_collections.ansible.windows.plugins.modules.win_ping.ps1": {"path": "/home/alexandre/ansible/.venv/lib/python3.12/site-packages/ansible_collections/ansible/windows/plugins/modules/win_ping.ps1", "script": ""}, "Ansible.Basic.cs": {"path": "/home/alexandre/ansible/.venv/lib/python3.12/site-packages/ansible/module_utils/csharp/Ansible.Basic.cs", "script": ""}, "Ansible.ModuleUtils.AddType.psm1": {"path": "/home/alexandre/ansible/.venv/lib/python3.12/site-packages/ansible/module_utils/powershell/Ansible.ModuleUtils.AddType.psm1", "script": ""}}, "actions": [{"name": "module_wrapper.ps1", "params": {"Script": "ansible_collections.ansible.windows.plugins.modules.win_ping.ps1", "Environment": {}, "Variables": [{"Name": "complex_args", "Value": {"_ansible_check_mode": false, "_ansible_no_log": false, "_ansible_debug": false, "_ansible_diff": false, "_ansible_verbosity": 0, "_ansible_version": "2.19.2", "_ansible_module_name": "win_ping", "_ansible_syslog_facility": "LOG_USER", "_ansible_selinux_special_fs": ["fuse", "nfs", "vboxsf", "ramfs", "9p", "vfat"], "_ansible_socket": null, "_ansible_shell_executable": "/bin/sh", "_ansible_keep_remote_files": false, "_ansible_tmpdir": ".\\.", "_ansible_remote_tmp": "%TEMP%", "_ansible_ignore_unknown_opts": false, "_ansible_target_log_info": null, "_ansible_tracebacks_for": []}, "Scope": "Global"}], "CSharpModules": ["Ansible.Basic.cs"], "PowerShellModules": ["Ansible.ModuleUtils.AddType.psm1"], "ForModule": true}, "secure_params": {}}], "signed_hashlist": []}